// Regenerates src/lib/contracts/abi.ts from the Foundry build output.
// Usage: (cd contracts && forge build) && npm run contracts:abi
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const artifact = JSON.parse(
  readFileSync(`${root}contracts/out/ContriboRewards.sol/ContriboRewards.json`, "utf8"),
);

const output = `// Generated by scripts/generate-contract-abi.mjs from contracts/src/ContriboRewards.sol.
// Do not edit by hand; run \`npm run contracts:abi\` after changing the contract.

export const contriboRewardsAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;
`;

writeFileSync(`${root}src/lib/contracts/abi.ts`, output);
console.log(`Wrote ${artifact.abi.length} ABI entries to src/lib/contracts/abi.ts`);
